// Ricoh SP 3710SF - counter.asp -> JSON
// Validado contra HTML real. Nota: "Fax" tem </b> antes de </td> no HTML.
var html = value;
var r = {};

// Extrai 3 numeros de uma linha da tabela apos o label
// Suporta tag extra apos label (ex: Fax</b></td>)
function row3(label) {
  var m = html.match(
    new RegExp('>' + label + '(?:<[^>]*>)?<\\/td>[\\s\\S]*?<td[^>]*>(\\d+)<\\/td>[\\s\\S]*?<td[^>]*>(\\d+)<\\/td>[\\s\\S]*?<td[^>]*>(\\d+)<')
  );
  return m ? [parseInt(m[1],10), parseInt(m[2],10), parseInt(m[3],10)] : [0,0,0];
}

// Extrai valor unico apos label (Page Total, Duplex Total Page)
// Estrutura: label</td> <td>:</td> <td>VALOR</td>
function single(label) {
  var esc = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  var m = html.match(
    new RegExp('>' + esc + '<\\/td>[\\s\\S]*?<\\/td>[\\s\\S]*?<td[^>]*>(\\d+)<')
  );
  return m ? parseInt(m[1], 10) : 0;
}

var p = row3('Printer'); r.printer_total = p[0]; r.printer_color = p[1]; r.printer_black = p[2];
var s = row3('Scanner'); r.scanner_total = s[0]; r.scanner_color = s[1]; r.scanner_black = s[2];
var c = row3('Copier');  r.copier_total  = c[0]; r.copier_color  = c[1]; r.copier_black  = c[2];
var f = row3('Fax');     r.fax_total     = f[0]; r.fax_reception = f[1]; r.fax_transmission = f[2];

r.page_total   = single('Page Total');
r.duplex_total = single('Duplex Total Page');

return JSON.stringify(r);

// Ricoh SP 3710SF - machinei.asp -> JSON
// Estrutura de cada campo: >Label</td> <td>:</td> <td>VALOR</td>
// Machine ID tem espaco extra no HTML: "5179Z311256 " -- trim() aplicado.
var html = value;
var r = {};

function ex(label) {
  var esc = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  var m = html.match(
    new RegExp('>' + esc + '<\\/td>[\\s\\S]*?<\\/td>[\\s\\S]*?<td[^>]*>([^<]+)<')
  );
  return m ? m[1].trim() : '';
}

r.firmware_version  = ex('Firmware Version');
r.engine_fw_version = ex('Engine FW Version');
r.machine_id        = ex('Machine ID');
r.fax_card          = ex('Fax Card');
r.total_memory      = ex('Total Memory');

return JSON.stringify(r);

// Ricoh SP 3710SF - card.asp -> JSON
// Validado contra HTML real do equipamento.
var html = value;
var r = {};

// Extrai campo de texto simples: >Label</td> <td>:</td> <td>&nbsp;VALOR</td>
function ex(label) {
  var esc = label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  var m = html.match(
    new RegExp('>' + esc + '<\\/td>[\\s\\S]*?<\\/td>\\s*<td nowrap>&nbsp;([^<]+)<')
  );
  return m ? m[1].trim() : '';
}

r.ethernet_speed   = ex('Ethernet Speed');
r.ipp_name         = ex('IPP Printer Name');
r.network_version  = ex('Network Version');
r.mac_address      = ex('Ethernet MAC Address');
r.active_interface = ex('Active Interface');
r.wifi_direct_ip   = ex('Wi-Fi Direct IP Address');

// DHCP: radio button - value="0" checked = Inactive, value="1" checked = Active
var dhcp = html.match(/<input type="radio" value="(\d)" name="R1"[^>]*checked/);
r.dhcp_status = dhcp ? (dhcp[1] === '1' ? 'Active' : 'Inactive') : 'Unknown';

// IP, Mascara e Gateway: inputs no bloco Manual (D05-D08, D09-D012, D013-D016)
// O bloco Auto usa D5-D8 (sem zero inicial) -- nao interfere.
function ip4(a, b, c, d) {
  var m = html.match(
    new RegExp('name="' + a + '"[^>]*value="(\\d+)"[\\s\\S]*?' +
               'name="' + b + '"[^>]*value="(\\d+)"[\\s\\S]*?' +
               'name="' + c + '"[^>]*value="(\\d+)"[\\s\\S]*?' +
               'name="' + d + '"[^>]*value="(\\d+)"')
  );
  return m ? m[1] + '.' + m[2] + '.' + m[3] + '.' + m[4] : '';
}

r.ip_address  = ip4('D05', 'D06', 'D07', 'D08');
r.subnet_mask = ip4('D09', 'D010', 'D011', 'D012');
r.gateway     = ip4('D013', 'D014', 'D015', 'D016');

return JSON.stringify(r);

// Ricoh SP 3710SF - main.asp -> JSON
// Validado contra HTML real do equipamento (firmware V1.04)
var html = value;
var r = {};

// Decode HTML numeric entities (Device Status usa &#N; encoding)
function decEnt(s) {
  return s.replace(/&#(\d+);/g, function(m, n) {
    return String.fromCharCode(parseInt(n, 10));
  }).replace(/&nbsp;/g, '').replace(/&amp;/g, '&').trim();
}

var m;
// Model Name: <td>Model Name</td><td>:</td><td>SP 3710SF&nbsp;</td>
m = html.match(/>Model Name<\/td>[\s\S]*?<\/td>[\s\S]*?<td[^>]*>([^<&]+)/);
r.model = m ? m[1].trim() : '';

// Location: <div id="a1">Administracao&nbsp;</div>
m = html.match(/id="a1">([^<&]+)/);
r.location = m ? m[1].trim() : '';

// Contact: <div id="a2">Marcio/Juliano&nbsp;</div>
m = html.match(/id="a2">([^<&]+)/);
r.contact = m ? m[1].trim() : '';

// Host Name: <td nowrap>3710SF-19A754</td>
m = html.match(/>Host Name<\/td>[\s\S]*?<\/td>[\s\S]*?<td[^>]*nowrap>([^<]+)/);
r.hostname = m ? m[1].trim() : '';

// Device Status: codificado como HTML entities (ex: &#82;&#101;... = "Ready")
m = html.match(/>Device Status<\/td>[\s\S]*?<td[^>]*nowrap>((?:&#\d+;|[^<])+)/);
r.device_status = m ? decEnt(m[1]) : '';

// Print Cartridge Remaining Level (inteiro 0-5)
m = html.match(/Remaining Level\s*(\d+)/);
r.cartridge_level = m ? parseInt(m[1], 10) : -1;

// Parser generico de bandeja: extrai <tr> pelo nome e coleta tds
function parseTray(trayName) {
  var re = new RegExp('>' + trayName + '<\\/td>([\\s\\S]*?)<\\/tr>');
  var row = html.match(re);
  if (!row) return { status: 'Unknown', size: 'Unknown', type: 'Unknown' };
  var tds = row[1].match(/<td[^>]*>([\s\S]*?)<\/td>/g) || [];
  var texts = tds.map(function(td) {
    return td.replace(/<[^>]+>/g, '').replace(/&nbsp;/g, '').replace(/\s+/g, ' ').trim();
  }).filter(function(t) { return t.length > 0; });
  // texts[0]=status, texts[1]=size, texts[2]=paper type
  return {
    status: texts[0] || 'Unknown',
    size:   texts[1] || 'Unknown',
    type:   texts[2] || 'Unknown'
  };
}

var t1 = parseTray('Tray 1');
r.tray1_status = t1.status; r.tray1_size = t1.size; r.tray1_type = t1.type;

var bp = parseTray('Bypass Tray');
r.bypass_status = bp.status; r.bypass_size = bp.size; r.bypass_type = bp.type;

return JSON.stringify(r);
